H,W=19,29
a=[[6]*W for _ in range(H)]
ones={2:[5,6,9,12,13,15,20,21,23],3:[5],4:[5],5:[5],6:[5,26],7:[5,26],8:[5],9:[26],10:[5],11:[26],12:[26],13:[5,9,10,11,14,17,23,26],14:[5],15:[26],16:[5,7,8,11,12,14,15,17,18,20,21,22,26]}
for r,cs in ones.items():
 for c in cs:a[r][c]=1
assert sum(v==1 for row in a for v in row)==len([c for cs in ones.values() for c in cs])
o=[row[:] for row in a]
# Fill broken horizontal marker rows with at least three source marks.
for r,cs in ones.items():
 if len(cs)>=3:
  for c in range(min(cs),max(cs)+1):
   if a[r][c]!=1:o[r][c]=2
# Bridge the two repeated vertical boundary marker columns.
for c in (5,26):
 rs=[r for r in range(H) if a[r][c]==1]
 for r in range(min(rs),max(rs)+1):
  if a[r][c]!=1:o[r][c]=2
import json
assert len(o)==19 and all(len(row)==29 for row in o)
print(json.dumps({'action':'submit','grid':o},separators=(',',':')))

