a=[[6]*W for _ in range(H)]
coords={2:[5,6,9,12,13,15,20,21,23],3:[5],4:[5],5:[5],6:[5,26],7:[5,26],8:[5],9:[26],10:[5],11:[26],12:[26],13:[5,9,10,11,14,17,23,26],14:[5],15:[26],16:[5,7,8,11,12,14,15,17,18,20,21,22,26]}
for r,cs in coords.items():
 for c in cs:a[r][c]=1
o=[row[:] for row in a]
# Bridge only short interruptions (up to three background cells) between consecutive markers on a shared row or column.
for r in range(H):
 cs=[c for c in range(W) if a[r][c]==1]
 for x,y in zip(cs,cs[1:]):
  if 1<=y-x-1<=3:
   for c in range(x+1,y):o[r][c]=2
for c in range(W):
 rs=[r for r in range(H) if a[r][c]==1]
 for x,y in zip(rs,rs[1:]):
  if 1<=y-x-1<=3:
   for r in range(x+1,y):o[r][c]=2
import json
assert len(o)==19 and all(len(row)==29 for row in o) and all(v in range(10) for row in o for v in row)
print(json.dumps({'action':'submit','grid':o},separators=(',',':')))

